export type HandoffScope={tenant:string;property:string;actor:string};
export type Handoff={id:string;session:string;sender:string;receiver:string;amount:string;reason:string;createdAt:string;outcome:'pending'|'accepted'|'rejected'|'cancelled';resolvedBy:string|null;resolutionReason:string|null};
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
function object(v:unknown):Record<string,unknown>{if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid handoff data.');return v as Record<string,unknown>}
function text(v:unknown){if(typeof v!=='string'||!v.trim()||v.length>500)throw Error('Incomplete handoff data.');return v}
export function readHandoffs(value:unknown,scope:HandoffScope,before:string|null=null){
 const r=object(value);if(!Object.values(scope).every(uuid)||r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.currency!=='USD'||!['property','participant'].includes(String(r.scope))||r.live_view!==true||!Array.isArray(r.entries)||r.entries.length>100)throw Error('Handoff workspace changed.');
 let previous=before;const entries:Handoff[]=r.entries.map(value=>{const h=object(value);if(!uuid(h.handoff_id)||!uuid(h.session_id)||!uuid(h.sender_id)||!uuid(h.receiver_id)||h.sender_id===h.receiver_id||(previous!==null&&h.handoff_id>=previous)||typeof h.amount_minor!=='string'||!/^[1-9][0-9]{0,11}$/.test(h.amount_minor)||!['pending','accepted','rejected','cancelled'].includes(String(h.outcome)))throw Error('Invalid handoff entry.');previous=h.handoff_id;
  if(r.scope==='participant'&&h.sender_id!==scope.actor&&h.receiver_id!==scope.actor)throw Error('Handoff belongs to other staff.');
  if(h.outcome==='pending'){if(h.resolved_by!==null||h.resolution_reason!==null||h.resolved_at!==null)throw Error('Pending handoff has a resolution.')}else{if(!uuid(h.resolved_by)||h.resolved_by!==(h.outcome==='cancelled'?h.sender_id:h.receiver_id))throw Error('Invalid handoff acknowledgment.');text(h.resolution_reason);text(h.resolved_at)}
  return {id:h.handoff_id,session:h.session_id,sender:h.sender_id,receiver:h.receiver_id,amount:h.amount_minor,reason:text(h.reason),createdAt:text(h.created_at),outcome:h.outcome as Handoff['outcome'],resolvedBy:h.resolved_by as string|null,resolutionReason:h.resolution_reason as string|null};});
 if(r.next_before!==null&&(!uuid(r.next_before)||entries.length!==100||r.next_before!==entries[99].id))throw Error('Invalid handoff page cursor.');return {entries,next:r.next_before as string|null};
}export type HandoffDecision={scope:HandoffScope;request:string;handoff:string;outcome:'accepted'|'rejected'|'cancelled';reason:string;amount:string};
export function prepareHandoffDecision(scope:HandoffScope,request:string,h:Handoff,outcome:string,reason:string):HandoffDecision{
 if(!Object.values(scope).every(uuid)||!uuid(request)||!uuid(h.id)||h.outcome!=='pending'||!['accepted','rejected','cancelled'].includes(outcome)||scope.actor!==(outcome==='cancelled'?h.sender:h.receiver)||typeof h.amount!=='string'||!/^[1-9][0-9]{0,11}$/.test(h.amount)||reason!==reason.trim()||reason.length<4||reason.length>500||/[\x00-\x1f\x7f]/.test(reason))throw Error('Review the handoff decision and explanation.');
 return {scope:{...scope},request,handoff:h.id,outcome:outcome as HandoffDecision['outcome'],reason,amount:h.amount};
}
export function handoffDecisionArgs(r:HandoffDecision){return {p_tenant:r.scope.tenant,p_property:r.scope.property,p_handoff:r.handoff,p_request:r.request,p_outcome:r.outcome,p_reason:r.reason,p_confirmed:true}}
export function readHandoffDecisionReceipt(value:unknown,r:HandoffDecision){const v=object(value);if(v.schema_version!==1||v.tenant_id!==r.scope.tenant||v.property_id!==r.scope.property||v.actor_id!==r.scope.actor||v.handoff_id!==r.handoff||v.request_id!==r.request||v.outcome!==r.outcome||v.reason!==r.reason||v.amount_minor!==r.amount||v.bank_deposit_verified!==false||typeof v.replayed!=='boolean')throw Error('Handoff receipt does not match the saved decision.');text(v.created_at);return v}
export function readHandoffDecisionStatus(value:unknown,r:HandoffDecision){const v=object(value);if(v.schema_version!==1||v.tenant_id!==r.scope.tenant||v.property_id!==r.scope.property||v.actor_id!==r.scope.actor||v.request_id!==r.request||v.kind!=='resolve'||typeof v.found!=='boolean')throw Error('Handoff recovery scope changed.');if(!v.found){if(v.result!==null)throw Error('Invalid handoff recovery.');return null}return readHandoffDecisionReceipt(v.result,r)}
type Store=Pick<Storage,'getItem'|'setItem'|'removeItem'>;
function decisionKey(s:HandoffScope,id:string){if(!Object.values(s).every(uuid)||!uuid(id))throw Error('Invalid handoff scope.');return 'irp.handoff.decision.v1:'+ [s.tenant,s.property,s.actor,id].join(':')}
export function loadHandoffDecision(store:Store,scope:HandoffScope,handoff:string):HandoffDecision|null{const raw=store.getItem(decisionKey(scope,handoff));if(raw===null)return null;const r=object(JSON.parse(raw)),s=object(r.scope);if(s.tenant!==scope.tenant||s.property!==scope.property||s.actor!==scope.actor||r.handoff!==handoff||!uuid(r.request)||!['accepted','rejected','cancelled'].includes(String(r.outcome))||typeof r.amount!=='string'||!/^[1-9][0-9]{0,11}$/.test(r.amount)||typeof r.reason!=='string'||r.reason!==r.reason.trim()||r.reason.length<4||r.reason.length>500||/[\x00-\x1f\x7f]/.test(r.reason))throw Error('Invalid saved handoff decision. Preserve it for recovery.');return {scope:{...scope},handoff,request:r.request,outcome:r.outcome as HandoffDecision['outcome'],reason:r.reason,amount:r.amount}}
export function saveHandoffDecision(store:Store,r:HandoffDecision){const key=decisionKey(r.scope,r.handoff),encoded=JSON.stringify(r);loadHandoffDecision({getItem:()=>encoded,setItem:()=>{},removeItem:()=>{}},r.scope,r.handoff);const prior=loadHandoffDecision(store,r.scope,r.handoff);if(prior&&JSON.stringify(prior)!==encoded)throw Error('Resolve the pending handoff decision first.');store.setItem(key,encoded);if(store.getItem(key)!==encoded)throw Error('Unable to preserve handoff decision.');loadHandoffDecision(store,r.scope,r.handoff)}
export function clearHandoffDecision(store:Store,r:HandoffDecision){const prior=loadHandoffDecision(store,r.scope,r.handoff);if(prior&&prior.request!==r.request)throw Error('Another handoff decision is pending.');const key=decisionKey(r.scope,r.handoff);store.removeItem(key);if(store.getItem(key)!==null)throw Error('Unable to clear handoff decision.')}export function readHandoffOptions(value:unknown,scope:HandoffScope,session:string,search:string){const r=object(value);if(!Object.values(scope).every(uuid)||!uuid(session)||r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.session_id!==session||r.currency!=='USD'||r.search!==search||typeof r.paused!=='boolean'||typeof r.refine_search!=='boolean'||!Array.isArray(r.receivers)||r.receivers.length>50)throw Error('Handoff options changed.');
 for(const key of ['counted_minor','reserved_minor','available_minor'])if(typeof r[key]!=='string'||!/^(0|[1-9][0-9]{0,11})$/.test(r[key] as string))throw Error('Invalid cash availability.');
 if(BigInt(r.counted_minor as string)-BigInt(r.reserved_minor as string)!==BigInt(r.available_minor as string))throw Error('Handoff cash does not reconcile.');const seen=new Set<string>();const receivers=r.receivers.map(value=>{const v=object(value);if(!uuid(v.user_id)||v.user_id===scope.actor||seen.has(v.user_id))throw Error('Invalid handoff receiver.');seen.add(v.user_id);return {id:v.user_id,label:text(v.label)}});return {available:r.available_minor as string,paused:r.paused,refineSearch:r.refine_search,receivers};
}
export type HandoffCreate={scope:HandoffScope;session:string;request:string;receiver:string;amount:string;reason:string};
export function prepareHandoffCreate(scope:HandoffScope,session:string,request:string,options:ReturnType<typeof readHandoffOptions>,receiver:string,amount:string,reason:string):HandoffCreate{
 if(!Object.values(scope).every(uuid)||!uuid(session)||!uuid(request)||options.paused||!options.receivers.some(x=>x.id===receiver)||!/^[1-9][0-9]{0,11}$/.test(amount)||BigInt(amount)>BigInt(options.available)||reason!==reason.trim()||reason.length<4||reason.length>500||/[\x00-\x1f\x7f]/.test(reason))throw Error('Review the receiver, available cash and explanation.');return {scope:{...scope},session,request,receiver,amount,reason};
}
export function handoffCreateArgs(r:HandoffCreate){return {p_tenant:r.scope.tenant,p_property:r.scope.property,p_session:r.session,p_request:r.request,p_receiver:r.receiver,p_amount_minor:r.amount,p_reason:r.reason,p_confirmed:true}}
export function readHandoffCreateReceipt(value:unknown,r:HandoffCreate){const v=object(value);if(v.schema_version!==1||v.tenant_id!==r.scope.tenant||v.property_id!==r.scope.property||v.sender_id!==r.scope.actor||v.receiver_id!==r.receiver||v.session_id!==r.session||v.handoff_id!==r.request||v.amount_minor!==r.amount||v.reason!==r.reason||v.bank_deposit_verified!==false||typeof v.replayed!=='boolean')throw Error('Handoff receipt does not match the request.');text(v.created_at);return v}export function readHandoffCreateStatus(value:unknown,r:HandoffCreate){const v=object(value);if(v.schema_version!==1||v.tenant_id!==r.scope.tenant||v.property_id!==r.scope.property||v.actor_id!==r.scope.actor||v.request_id!==r.request||v.kind!=='create'||typeof v.found!=='boolean')throw Error('Handoff recovery scope changed.');if(!v.found){if(v.result!==null)throw Error('Invalid handoff recovery result.');return null}return readHandoffCreateReceipt(v.result,r)}
function createKey(scope:HandoffScope,session:string){return decisionKey(scope,session).replace('irp.handoff.decision.v1:','irp.handoff.create.v1:')}
function checkedCreate(value:unknown,scope:HandoffScope,session:string):HandoffCreate{const r=object(value),s=object(r.scope);if(s.tenant!==scope.tenant||s.property!==scope.property||s.actor!==scope.actor||r.session!==session||!uuid(r.request)||!uuid(r.receiver)||r.receiver===scope.actor||typeof r.amount!=='string'||!/^[1-9][0-9]{0,11}$/.test(r.amount)||typeof r.reason!=='string'||r.reason!==r.reason.trim()||r.reason.length<4||r.reason.length>500||/[\x00-\x1f\x7f]/.test(r.reason))throw Error('Invalid saved handoff. Preserve it for recovery.');return {scope:{...scope},session,request:r.request,receiver:r.receiver,amount:r.amount,reason:r.reason}}
export function loadHandoffCreate(store:Store,scope:HandoffScope,session:string){const raw=store.getItem(createKey(scope,session));return raw===null?null:checkedCreate(JSON.parse(raw),scope,session)}
export function saveHandoffCreate(store:Store,r:HandoffCreate){const checked=checkedCreate(r,r.scope,r.session),prior=loadHandoffCreate(store,r.scope,r.session),encoded=JSON.stringify(checked);if(prior&&JSON.stringify(prior)!==encoded)throw Error('Resolve the pending handoff first.');const key=createKey(r.scope,r.session);store.setItem(key,encoded);if(store.getItem(key)!==encoded)throw Error('Unable to preserve handoff request.')}
export function clearHandoffCreate(store:Store,r:HandoffCreate){const prior=loadHandoffCreate(store,r.scope,r.session);if(prior&&prior.request!==r.request)throw Error('A different handoff is pending.');const key=createKey(r.scope,r.session);store.removeItem(key);if(store.getItem(key)!==null)throw Error('Unable to clear saved handoff.')}
export function readHandoffCreateCancellation(value:unknown,r:HandoffCreate){const v=object(value);if(v.schema_version!==1||v.tenant_id!==r.scope.tenant||v.property_id!==r.scope.property||v.actor_id!==r.scope.actor||v.request_id!==r.request||v.cancelled!==true||typeof v.replayed!=='boolean')throw Error('Handoff cancellation does not match the pending request.');text(v.created_at);return v}
